style.css:
/* 1. Main Background & Calendar Canvas */
body, 
div[role="main"], 
div[role="region"],
[data-view-family] {
  background-color: #ffe6f0 !important;
}

/* 2. Top Header Navigation Bar */
header, 
div[role="banner"] {
  background-color: #ffb3d9 !important;
}

/* 3. Primary Action Buttons & Interactive Text */
button[aria-label], 
div[role="button"],
a[href*="calendar"] {
  background-color: #ff80bf !important;
  color: #ffffff !important;
}
